cd /tmp/<path>; ls; cat > /tmp/sim.py <<'E'
import sys,re
prog=[]
for l in open(sys.argv[1]):
    l=l.split(';')[0].strip()
    if l: prog.append(l.split())
R=dict(a=0,b=0,c=0,d=0)
v=lambda x:R[x] if x in R else int(x)
pc=0;n=0;s=0
while 0<=pc<len(prog):
    i=prog[pc];o=i[0];n+=1;nx=pc+1
    if o=='set':R[i[1]]=v(i[2])%65536
    elif o=='add':R[i[1]]=(R[i[1]]+v(i[2]))%65536
    elif o=='mul':R[i[1]]=(R[i[1]]*v(i[2]))%65536
    elif o=='mod':
        if v(i[2])>0:R[i[1]]%=v(i[2])
    elif o=='dec':R[i[1]]=max(0,R[i[1]]-1)
    elif o=='jnz':
        if v(i[1])!=0:nx=pc+v(i[2])
    elif o=='skp':
        if v(i[1])<v(i[2]):nx=pc+2
    elif o=='out':s+=v(i[1])
    else:raise Exception(i)
    pc=nx
print(s,n)
E
